			    var vsCurrMonth     = moment().subtract(0, "months").format("YYYYMM");      // 현재월
			    var vsCurrYear      = moment().subtract(0, "months").format("YYYY");        // 현재년
			    var vsUserId        = util.Auth.getUserInfo(app, "USER_ID");                // 상담사아이디
			    var vsGroupAuthrt   = util.Auth.getUserInfo(app, "GROUP_AUTHRT_SE_CD");     // 종사자역할구분코드 
			    
			    // 종사자 역할구분코드 3이면 상담원ID 기준 조회 되도록 셋팅
			    if (vsGroupAuthrt == 340) { 
			        app.lookup("dmSearchParam").setValue("CONSTT_ID", vsUserId);
			    }
			    
			    app.lookup("dmSearchParam").setValue("P_TODAY", vsToday);
			    app.lookup("dmSearchParam").setValue("CURR_MONTH", vsCurrMonth);    
			    app.lookup("dmSearchParam").setValue("CURR_YEAR", vsCurrYear);
			    app.lookup("dmSearchParam").setValue("NTABRD_ESNTAL_NO", "10142");  // 게시판 고유번호_공지사항 조회 관리자공지
